package com.sgasubtitler.engine;
import java.io.*;
public final class LzDecoder { public static byte[] decode(byte[] data,int mask,int base)throws IOException{int shift=Integer.numberOfTrailingZeros(mask),offsetMask=(~mask)&0xffff,pos=0;var out=new ByteArrayOutputStream();while(pos+1<data.length){int flags=((data[pos]&255)<<8)|(data[pos+1]&255);pos+=2;for(int bit=0;bit<16&&pos+1<data.length;bit++){int word=((data[pos]&255)<<8)|(data[pos+1]&255);pos+=2;if((flags&(1<<(15-bit)))==0){out.write(word>>>8);out.write(word);}else{int count=((word&mask)>>>shift),offset=word&offsetMask;if(count==0&&offset==0){out.write(data,pos,data.length-pos);return out.toByteArray();}count+=base;byte[] prior=out.toByteArray();if(offset<=0||offset>prior.length)throw new IOException("Référence LZ invalide");for(int j=0;j<count*2;j++){prior=out.toByteArray();out.write(prior[prior.length-offset]);}}}}return out.toByteArray();}}
